import numpy as np

def fisher_information_scalar(log_likelihood_grad, samples, theta):
    scores = np.array([log_likelihood_grad(x, theta) for x in samples])
    fisher_info = np.mean(scores**2)
    return fisher_info

def fisher_information_matrix(log_likelihood_hessian, samples, theta):
    n = len(samples)
    d = len(theta)
    fisher_matrix = np.zeros((d, d))
    for x in samples:
        hess = log_likelihood_hessian(x, theta)
        fisher_matrix += hess
    fisher_matrix = -fisher_matrix / n
    return fisher_matrix

def cramer_rao_bound(fisher_info, n_samples):
    crlb = 1.0 / (n_samples * fisher_info)
    return crlb

def jeffreys_prior(fisher_info_func, theta_range, n_points=100):
    thetas = np.linspace(theta_range[0], theta_range[1], n_points)
    prior = np.array([np.sqrt(fisher_info_func(t)) for t in thetas])
    prior = prior / np.sum(prior)
    return thetas, prior

def bernoulli_score(x, p):
    return (x - p) / (p * (1 - p))

def bernoulli_hessian(x, p):
    return -x / (p**2) - (1-x) / ((1-p)**2)

samples = np.array([1, 0, 1, 1, 0, 1, 0, 1])
fi = fisher_information_scalar(bernoulli_score, samples, 0.6)
print(f"Fisher information: {fi:.4f}")
print(f"Cramer-Rao bound: {cramer_rao_bound(fi, len(samples)):.4f}")
